pragma solidity 0.8.34;

/// Reconstructed candidate. Names and comments are analytical labels.
contract FeeHelper {
    function getFee(address token) external view returns(uint256) {
        address pool;
        if (token == 0x4200000000000000000000000000000000000006) pool=0x72AB388E2E2F6FaceF59E3C3FA2C4E29011c2D38;
        else if (token == 0xcbB7C0000aB88B473b1f5aFd9ef808440eed33Bf) pool=0xb94b22332ABf5f89877A14Cc88f2aBC48c34B3Df;
        else return 0;
        return fee(pool);
    }

    function fee(address pool) internal view returns (uint256) {
        bool ok;
        int256 tick;
        uint256 index;
        uint256 cardinality;
        assembly ("memory-safe") {
            let p := mload(0x40)
            mstore(p, shl(224, 0x3850c7bd))
            ok := staticcall(8000, pool, p, 4, p, 128)
            ok := and(ok, iszero(lt(returndatasize(), 128)))
            tick := mload(add(p, 32))
            index := mload(add(p, 64))
            cardinality := mload(add(p, 96))
        }
        if (!ok || tick < -887272 || tick > 887272 || cardinality < 2 || cardinality > 65535 || index >= cardinality) return 0;
        (bool valid, uint32 time, int56 cumulative) = observation(pool, index);
        if (!valid || time != uint32(block.timestamp)) return 0;
        uint256 previous = index == 0 ? cardinality - 1 : index - 1;
        (bool previousValid, uint32 previousTime, int56 previousCumulative) = observation(pool, previous);
        if (!previousValid) return 0;
        uint32 elapsed;
        int56 accumulated;
        unchecked {
            elapsed = time - previousTime;
            accumulated = cumulative - previousCumulative;
        }
        if (elapsed == 0) return 0;
        int256 average = int256(accumulated) / int256(uint256(elapsed));
        if (average < -887272 || average > 887272) return 0;
        int256 delta = tick - average;
        uint256 magnitude = uint256(delta < 0 ? -delta : delta);
        uint256 result = (magnitude + 1) * 10;
        return result > 1000 ? 1000 : result;
    }

    function observation(address pool, uint256 index) internal view returns (bool ok, uint32 time, int56 cumulative) {
        assembly ("memory-safe") {
            let p := mload(0x40)
            mstore(p, shl(224, 0x252c09d7))
            mstore(add(p, 4), index)
            ok := staticcall(6000, pool, p, 36, p, 128)
            ok := and(ok, iszero(lt(returndatasize(), 128)))
            let rawTime := mload(p)
            let rawCumulative := mload(add(p, 32))
            time := and(rawTime, 0xffffffff)
            cumulative := signextend(6, rawCumulative)
            ok := and(
                and(eq(time, rawTime), eq(cumulative, rawCumulative)),
                and(ok, eq(mload(add(p, 96)), 1))
            )
        }
    }
}
